@startuml
class School {
  +name : string
}

class Person {
  +firstName : string
  +lastName : string
}

class Teacher extends Person {
  +emailAddress : string
}

class Student extends Person {
}

class TeachingRelationship {
  +hours : int
}

class ClassGroup {
  +name : string
}

class Room {
  +name : string
}

class Classroom extends Room {
  +capacity : int
}

class Gym extends Room {
  +size : float
}

School "1" -- "1..*" Teacher : employs
School "1" -- "0..1" Teacher : principal
Teacher "0..3" -- "1..*" School : teaches
Teacher "1" -- "*" TeachingRelationship
School "1" -- "*" TeachingRelationship

Student "1" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
Classroom "1" -- "1" ClassGroup : assigned to
School "1" -- "*" Room : consists of
ClassGroup "*" -- "10..31" Student : contains
@enduml

